var fileEl=document.getElementById('file'),W=document.getElementById('w'),H=document.getElementById('h'),
lock=document.getElementById('lock'),fmt=document.getElementById('fmt'),q=document.getElementById('q'),qv=document.getElementById('qv'),
go=document.getElementById('go'),dl=document.getElementById('dl'),note=document.getElementById('note'),
stats=document.getElementById('stats'),prev=document.getElementById('prev'),pw=document.getElementById('pw');
var img=new Image(),srcSize=0,srcName='image',ratio=1,outBlob=null,outUrl=null,busy=false;
function kb(b){return b<1024?b+' B':b<1048576?(b/1024).toFixed(1)+' KB':(b/1048576).toFixed(2)+' MB';}
q.addEventListener('input',function(){qv.textContent=q.value;});
fileEl.addEventListener('change',function(){
  var f=fileEl.files&&fileEl.files[0]; if(!f)return;
  if(!/^image\//.test(f.type)){note.textContent='That file is not an image.';return;}
  srcSize=f.size; srcName=f.name.replace(/\.[^.]+$/,'');
  var r=new FileReader();
  r.onload=function(e){
    img=new Image();
    img.onload=function(){
      ratio=img.width/img.height;
      W.value=img.width; H.value=img.height;
      go.disabled=false;
      note.textContent='Loaded '+img.width+' x '+img.height+' pixels, '+kb(srcSize)+'. Set the size you want.';
      WT.resize();
    };
    img.onerror=function(){note.textContent='That image could not be read.';};
    img.src=e.target.result;
  };
  r.readAsDataURL(f);
});
W.addEventListener('input',function(){
  if(!lock.checked||!ratio||busy)return; busy=true;
  var v=parseInt(W.value,10); if(v>0)H.value=Math.round(v/ratio); busy=false;
});
H.addEventListener('input',function(){
  if(!lock.checked||!ratio||busy)return; busy=true;
  var v=parseInt(H.value,10); if(v>0)W.value=Math.round(v*ratio); busy=false;
});
go.addEventListener('click',function(){
  var w=parseInt(W.value,10),h=parseInt(H.value,10);
  if(!(w>0&&h>0)){note.textContent='Enter a width and height greater than zero.';return;}
  if(w>12000||h>12000){note.textContent='That is very large. Keep each side under 12000 pixels.';return;}
  var c=document.createElement('canvas'); c.width=w; c.height=h;
  var ctx=c.getContext('2d');
  ctx.imageSmoothingQuality='high';
  if(fmt.value==='image/jpeg'){ctx.fillStyle='#fff';ctx.fillRect(0,0,w,h);}
  ctx.drawImage(img,0,0,w,h);
  c.toBlob(function(b){
    if(!b){note.textContent='Your browser could not produce that format. Try JPG.';return;}
    outBlob=b; if(outUrl)URL.revokeObjectURL(outUrl); outUrl=URL.createObjectURL(b);
    document.getElementById('s1').textContent=kb(srcSize);
    document.getElementById('s2').textContent=kb(b.size);
    document.getElementById('s3').textContent=w+' x '+h;
    stats.style.display=''; prev.src=outUrl; pw.style.display=''; dl.disabled=false;
    note.textContent='Done. Press Download to save it, or right click the preview and choose Save image as.';
    WT.resize();
  },fmt.value,parseInt(q.value,10)/100);
});
dl.addEventListener('click',function(){
  if(!outBlob)return;
  var ext=fmt.value==='image/png'?'png':fmt.value==='image/webp'?'webp':'jpg';
  var name=srcName+'-'+W.value+'x'+H.value+'.'+ext;
  try{
    var a=document.createElement('a');a.href=outUrl;a.download=name;
    document.body.appendChild(a);a.click();document.body.removeChild(a);
    note.textContent='Saved as '+name+'. Check your downloads folder.';
  }catch(e){
    window.open(outUrl,'_blank');
    note.textContent='Opened in a new tab. Right click it and choose Save image as.';
  }
  WT.resize();
});
